export const decodeEvtButton = (b: Uint8Array): EvtButton => decodeStruct(EVT_BUTTON, b) as EvtButton;

// 0xe0 STR_RAW_SAMPLES (stream): Decimated raw sensor samples of one lane for the diagnostics view. Sample i was taken at firstUs + i*periodUs.
/** STR_RAW_SAMPLES */
export const STR_RAW_SAMPLES: StructDesc = {
  name: 'StrRawSamples',
  size: 16,
  fields: [
    { name: 'lane', kind: 'scalar', type: 'u8' },
    { name: 'reserved', kind: 'scalar', type: 'u8' },
    { name: 'chunkSeq', kind: 'scalar', type: 'u16' },
    { name: 'periodUs', kind: 'scalar', type: 'u32' },
    { name: 'firstUs', kind: 'scalar', type: 'u64' },
    { name: 'samples', kind: 'tail', item: { kind: 'scalar', type: 'u16' } },
  ],
};
export type StrRawSamples = {
  lane: number;
  reserved: number;
  /** Counts chunks of this lane's stream, so the app sees drops */
  chunkSeq: number;
  periodUs: number;
  firstUs: bigint;
  samples: number[];
};
export const encodeStrRawSamples = (v: StrRawSamples): Uint8Array => encodeStruct(STR_RAW_SAMPLES, v);
export const decodeStrRawSamples = (b: Uint8Array): StrRawSamples => decodeStruct(STR_RAW_SAMPLES, b) as StrRawSamples;

// 0xf0 DBG_LOG (stream): Free-text firmware log line (bring-up aid; mnemonics stay stable like the hub's log vocabulary).
/** DBG_LOG */
export const DBG_LOG: StructDesc = {
  name: 'DbgLog',
  size: 12,
  fields: [
    { name: 'level', kind: 'scalar', type: 'u8' },
    { name: 'reserved', kind: 'bytes', size: 3 },
    { name: 'sysUs', kind: 'scalar', type: 'u64' },
    { name: 'text', kind: 'tail', item: { kind: 'str' } },
  ],
};
export type DbgLog = {
  /** enum LogLevel */
  level: number;
  reserved: Uint8Array;
  sysUs: bigint;
  text: string;
};
export const encodeDbgLog = (v: DbgLog): Uint8Array => encodeStruct(DBG_LOG, v);
export const decodeDbgLog = (b: Uint8Array): DbgLog => decodeStruct(DBG_LOG, b) as DbgLog;

export type MsgKind = 'request' | 'event' | 'stream';

export interface MsgDesc {
  readonly id: number;
  readonly name: string;
  readonly kind: MsgKind;
  /** Requests: payload host → device. */
  readonly req?: StructDesc;
  /** Requests: response payload (starts with status). */
  readonly rsp?: StructDesc;
  /** Events and streams: payload. */
  readonly body?: StructDesc;
}

